package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.util.*;
/** Repeatable local navigation benchmark. No contacts, calls, messages or audio. */
public final class JourneyTests extends Instrumentation {
    public void onCreate(Bundle b){start();}
    public void onStart(){Bundle result=new Bundle();Activity activity=null;try{
        getTargetContext().startActivity(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int attempt=0;attempt<50&&activity==null;attempt++){SystemClock.sleep(100);final Activity[] found={null};runOnMainSync(new Runnable(){public void run(){try{Class<?> type=Class.forName("android.app.ActivityThread");Object thread=type.getMethod("currentActivityThread").invoke(null);java.lang.reflect.Field records=type.getDeclaredField("mActivities");records.setAccessible(true);for(Object record:((java.util.Map<?,?>)records.get(thread)).values()){java.lang.reflect.Field member=record.getClass().getDeclaredField("activity");member.setAccessible(true);Object candidate=member.get(record);if(candidate instanceof MainActivity)found[0]=(Activity)candidate;}}catch(Exception e){throw new RuntimeException(e);}}});activity=found[0];}if(activity==null)throw new AssertionError("HOME did not resume");waitForIdleSync();
        final MainActivity home=(MainActivity)activity;for(int i=0;i<40&&!home.hasWindowFocus();i++)SystemClock.sleep(100);if(!home.hasWindowFocus())throw new AssertionError("HOME has no keyboard focus");final java.lang.reflect.Field screenField=MainActivity.class.getDeclaredField("screen");screenField.setAccessible(true);final Object screen=screenField.get(home);final java.lang.reflect.Field selected=screen.getClass().getDeclaredField("selected"),grid=screen.getClass().getDeclaredField("grid"),list=screen.getClass().getDeclaredField("list");selected.setAccessible(true);grid.setAccessible(true);list.setAccessible(true);runOnMainSync(new Runnable(){public void run(){home.onNewIntent(new Intent(getTargetContext(),MainActivity.class));try{selected.setInt(screen,0);}catch(Exception e){throw new RuntimeException(e);}}});sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();if(!grid.getBoolean(screen))throw new AssertionError("Leo menu not open");
        final ArrayList<Long> frames=new ArrayList<Long>();final Window window=activity.getWindow();final Window.OnFrameMetricsAvailableListener listener=new Window.OnFrameMetricsAvailableListener(){public void onFrameMetricsAvailable(Window w,FrameMetrics metrics,int dropped){synchronized(frames){frames.add(metrics.getMetric(FrameMetrics.TOTAL_DURATION)/1000000);}}};runOnMainSync(new Runnable(){public void run(){window.addOnFrameMetricsAvailableListener(listener,new Handler(Looper.getMainLooper()));}});
        long[] samples=new long[60];for(int i=0;i<samples.length;i++){long start=SystemClock.elapsedRealtimeNanos();sendKeyDownUpSync(i%2==0?KeyEvent.KEYCODE_DPAD_DOWN:KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();samples[i]=(SystemClock.elapsedRealtimeNanos()-start)/1000000;int expected=i%2==0?(list.getBoolean(screen)?1:3):0;if(!grid.getBoolean(screen)||selected.getInt(screen)!=expected)throw new AssertionError("Menu selection did not follow injected key "+i);SystemClock.sleep(70);}
        runOnMainSync(new Runnable(){public void run(){window.removeOnFrameMetricsAvailableListener(listener);}});synchronized(frames){Collections.sort(frames);if(!frames.isEmpty())result.putString("frames","navigation: n="+frames.size()+" p50="+frames.get(frames.size()/2)+"ms p95="+frames.get(Math.min(frames.size()-1,frames.size()*95/100))+"ms");}
        Arrays.sort(samples);result.putString("navigation","60 keys: dispatch-to-idle p50="+samples[30]+"ms p95="+samples[57]+"ms max="+samples[59]+"ms; not physical key-to-photon latency");
        ArrayList<String> launches=new ArrayList<String>();for(Class<?> type:new Class<?>[]{CalculatorActivity.class,QuickSettingsActivity.class,PersonalizationActivity.class}){long start=SystemClock.elapsedRealtime();Activity a=startActivitySync(new Intent(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();launches.add(type.getSimpleName()+"="+(SystemClock.elapsedRealtime()-start)+"ms");final Activity close=a;runOnMainSync(new Runnable(){public void run(){close.finish();}});waitForIdleSync();}result.putString("launches",launches.toString());
        result.putString("result","PASS navigation and three local pages");
    }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));}finally{if(activity!=null){final Activity home=activity;runOnMainSync(new Runnable(){public void run(){home.onBackPressed();}});}}
    finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
